// ============================================================
// Termo de busca do dia. Rotaciona pelo dia da semana para não
// procurar sempre a mesma coisa.
// Nicho: PODCAST E MESA DE DEBATE de futebol brasileiro.
// ============================================================

// --- edite aqui os temas do canal ---------------------------
const TERMOS_POR_DIA = [
  'podcast futebol brasileiro debate',      // domingo
  'mesa redonda brasileirao analise',        // segunda (pós-rodada)
  'entrevista jogador brasileirao',          // terça
  'debate libertadores analise',             // quarta
  'bastidores futebol brasileiro podcast',   // quinta
  'coletiva tecnico brasileirao',            // sexta
  'programa esportivo debate futebol'        // sábado
];
const DIAS_PARA_TRAS = 14;   // futebol envelhece rápido: janela curta
// ------------------------------------------------------------

const hoje = new Date();
const termo = TERMOS_POR_DIA[hoje.getDay() % TERMOS_POR_DIA.length];
const depois = new Date(hoje.getTime() - DIAS_PARA_TRAS * 86400000);

return [{
  json: {
    termo,
    published_after: depois.toISOString(),
    dia_semana: hoje.getDay()
  }
}];

// ============================================================
// Junta os vídeos das duas fontes (em alta + busca por tema),
// filtra o que não serve para virar corte e ranqueia o resto.
// ============================================================

// --- critérios (ajuste aqui) --------------------------------
const DUR_MIN_MIN = 12;     // duração mínima (podcast curto não rende 5 cortes)
const DUR_MAX_MIN = 75;     // duração máxima (acima disso o processamento fica lento)
// CC tem muito menos views que vídeo comum — piso baixo de propósito.
// Depois de ver o que aparece, você calibra.
const VIEWS_MIN = 3000;     // views mínimas
const IDIOMAS = ['pt'];     // prefixos aceitos ([] = qualquer idioma)
// Só aceita vídeo com licença Creative Commons (reuso permitido, exige crédito).
// Coloque false para aceitar qualquer licença.
const SO_CREATIVE_COMMONS = true;
// Nicho futebol: a categoria 17 (Esportes) agora é DESEJADA.
// Bloqueia só o que não tem fala pra transcrever.
// 10=Música 20=Gaming 1=Filme/Animação
const CATEGORIAS_BLOQUEADAS = ['10', '20', '1'];
// Em futebol, o que atrapalha é IMAGEM DE PARTIDA (não tem fala pra cortar,
// e é o conteúdo mais reivindicado do YouTube). 'ao vivo' e 'live' saíram da
// lista porque quase todo podcast é transmitido ao vivo antes de ser postado —
// vídeo longo demais já é barrado pela duração.
const TITULO_BLOQUEADO = [
  'melhores momentos', 'gols de', 'todos os gols', 'compacto',
  'resumo do jogo', 'assista os gols', 'lances do jogo',
  'clipe oficial', 'official video', 'lyric', 'gameplay', 'trailer',
  'fifa', 'efootball', 'shorts'
];
// ------------------------------------------------------------

function duracaoParaSegundos(iso) {
  const m = /^P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/.exec(iso || '');
  if (!m) return 0;
  const [, d, h, mi, s] = m.map(v => Number(v || 0));
  return d * 86400 + h * 3600 + mi * 60 + s;
}

function semAcento(t) {
  return (t || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

// Junta os `items` de todas as entradas (as duas fontes)
const brutos = [];
for (const entrada of $input.all()) {
  const lista = entrada.json.items || [];
  for (const v of lista) brutos.push(v);
}

if (!brutos.length) {
  throw new Error('Nenhuma das duas fontes devolveu vídeo. Verifique a credencial do YouTube e a cota.');
}

const vistos = new Set();
const candidatos = [];
const recusados = [];

for (const v of brutos) {
  const id = typeof v.id === 'string' ? v.id : (v.id && v.id.videoId);
  if (!id || vistos.has(id)) continue;
  vistos.add(id);

  const sn = v.snippet || {};
  const cd = v.contentDetails || {};
  const st = v.statistics || {};
  const stt = v.status || {};
  const licenca = stt.license || 'desconhecida';

  const titulo = (sn.title || '').trim();
  const categoria = String(sn.categoryId || '');
  const idioma = (sn.defaultAudioLanguage || sn.defaultLanguage || '').toLowerCase();
  const dur = duracaoParaSegundos(cd.duration);
  const views = Number(st.viewCount || 0);
  const tl = semAcento(titulo);

  const motivo = [];
  if (SO_CREATIVE_COMMONS && licenca !== 'creativeCommon') {
    motivo.push(`licença ${licenca}`);
  }
  if (!cd.duration) motivo.push('sem duração (faltou o videos.list)');
  if (dur && dur < DUR_MIN_MIN * 60) motivo.push(`curto (${Math.round(dur / 60)}min)`);
  if (dur > DUR_MAX_MIN * 60) motivo.push(`longo (${Math.round(dur / 60)}min)`);
  if (views < VIEWS_MIN) motivo.push(`poucas views (${views})`);
  if (CATEGORIAS_BLOQUEADAS.includes(categoria)) motivo.push(`categoria ${categoria}`);
  if (IDIOMAS.length && idioma && !IDIOMAS.some(p => idioma.startsWith(p))) {
    motivo.push(`idioma ${idioma}`);
  }
  const palavra = TITULO_BLOQUEADO.find(p => tl.includes(semAcento(p)));
  if (palavra) motivo.push(`título contém "${palavra}"`);
  if (/^P\d+D/.test(cd.duration || '')) motivo.push('duração absurda (live?)');

  if (motivo.length) {
    recusados.push({ titulo: titulo.slice(0, 55), motivo: motivo.join(', ') });
    continue;
  }

  candidatos.push({
    video_id: id,
    titulo,
    canal: (sn.channelTitle || '').trim(),
    url: `https://www.youtube.com/watch?v=${id}`,
    duracao_seg: dur,
    duracao_min: +(dur / 60).toFixed(1),
    views,
    categoria,
    idioma: idioma || 'nao informado',
    licenca,
    embutivel: stt.embeddable !== false,
    publicado_em: sn.publishedAt || null,
    // views por minuto: favorece vídeo denso em vez de só longo
    nota: Math.round(views / Math.max(1, dur / 60))
  });
}

candidatos.sort((a, b) => b.nota - a.nota);

if (!candidatos.length) {
  // Conta os motivos, pra você saber QUAL filtro está barrando tudo
  const porMotivo = {};
  for (const r of recusados) {
    for (const m of r.motivo.split(', ')) {
      const chave = m.replace(/\(.*\)/, '').trim();
      porMotivo[chave] = (porMotivo[chave] || 0) + 1;
    }
  }
  throw new Error(
    `Nenhum dos ${brutos.length} vídeos passou. Contagem por motivo: ` +
    JSON.stringify(porMotivo) +
    ` | Exemplos: ${JSON.stringify(recusados.slice(0, 4))}`
  );
}

return candidatos.map(c => ({
  json: { ...c, total_candidatos: candidatos.length, total_analisados: brutos.length }
}));

// ============================================================
// Compara os candidatos com o histórico e escolhe o melhor
// vídeo que ainda não foi usado.
// ============================================================

const candidatos = $input.all().map(i => i.json);

// O histórico vem do node do Data Table. Se a tabela estiver
// vazia, ele devolve nada — e aí tudo é inédito.
const historico = $('Histórico: já usados').all()
  .map(i => i.json)
  .filter(r => r && (r.video_id || r.videoId));

const usados = new Set(historico.map(r => String(r.video_id || r.videoId)));

const inedito = candidatos.find(c => !usados.has(String(c.video_id)));

if (!inedito) {
  throw new Error(
    `Todos os ${candidatos.length} candidatos de hoje já foram usados ` +
    `(${usados.size} no histórico). Nada novo para processar.`
  );
}

// Nome do arquivo que vai pro Drive e pro disco
function nomeSeguro(t) {
  return (t || '')
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[\\/:*?"<>|]/g, '-')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 70);
}

const arquivoLocal = `/home/node/files/origem_${inedito.video_id}.mp4`;

return [{
  json: {
    ...inedito,
    arquivo_local: arquivoLocal,
    nome_no_drive: `${nomeSeguro(inedito.titulo)} [${inedito.video_id}].mp4`,
    descartados_por_repeticao: candidatos.length - candidatos.filter(c => !usados.has(String(c.video_id))).length,
    total_no_historico: usados.size,
    // atribuição, para entrar na descrição do vídeo publicado
    // Creative Commons exige atribuição: este texto vai na descrição do vídeo publicado
    creditos: `Trecho de "${inedito.titulo}" por ${inedito.canal}\n${inedito.url}\n`
      + `Licença: Creative Commons Atribuição (CC BY) — https://creativecommons.org/licenses/by/3.0/`,
    licenca_original: inedito.licenca
  }
}];
